     6→// Age ratings supported by the content filtering system
     7→export type AgeRating =
     8→  // Movie ratings (MPAA)
     9→  | 'G'
    10→  | 'PG'
    11→  | 'PG-13'
    12→  | 'R'
    13→  | 'NC-17'
    14→  // TV ratings (TV Parental Guidelines)
    15→  | 'TV-Y'
    16→  | 'TV-Y7'
    17→  | 'TV-G'
    18→  | 'TV-PG'
    19→  | 'TV-14'
    20→  | 'TV-MA'
    21→  // Unrated content
    22→  | 'NR'
    23→  | 'UNRATED';
    24→
    25→// Age rating levels for filtering (lower = more restrictive)
    26→export const AGE_RATING_LEVELS: Record<AgeRating, number> = {
    27→  'TV-Y': 1,
    28→  'G': 1,
    29→  'TV-Y7': 2,
    30→  'TV-G': 2,
    31→  'PG': 3,
    32→  'TV-PG': 3,
    33→  'PG-13': 4,
    34→  'TV-14': 4,
    35→  'R': 5,
    36→  'TV-MA': 5,
    37→  'NC-17': 6,
    38→  'NR': 6,
    39→  'UNRATED': 6,
    40→};
    41→
    42→// Kids mode allowed ratings (G, PG, TV-Y, TV-Y7, TV-G, TV-PG)
    43→export const KIDS_MODE_ALLOWED_RATINGS: AgeRating[] = [
    44→  'G', 'PG', 'TV-Y', 'TV-Y7', 'TV-G', 'TV-PG'
    45→];
