   161→// Profile sync state
   162→export type SyncStatus = 'synced' | 'pending' | 'syncing' | 'error' | 'offline';
   163→
   164→export interface ProfileSyncState {
   165→  status: SyncStatus;
   166→  lastSyncedAt: number | null;
