   171→// Storage keys for profile data
   172→export const PROFILE_STORAGE_KEYS = {
   173→  profiles: '@profiles:list',
   174→  activeProfileId: '@profiles:active',
   175→  pinHashes: '@profiles:pins', // Stored securely
   176→  pinAttempts: '@profiles:pin_attempts',
   177→  syncQueue: '@profiles:sync_queue',
   178→  lastSync: '@profiles:last_sync',
   179→};
   180→
   181→// Maximum number of profiles allowed
   182→export const MAX_PROFILES = 6;
   183→
   184→// Helper function to get default max age rating based on profile type
   185→export function getDefaultMaxAgeRating(type: ProfileType): AgeRating {
   186→  switch (type) {
   187→    case 'kids':
   188→      return 'TV-PG';
   189→    case 'admin':
   190→    case 'standard':
   191→    default:
   192→      return 'NC-17'; // No restrictions for adults
   193→  }
   194→}
   195→
   196→// Helper function to check if a rating is allowed for a profile
   197→export function isRatingAllowedForProfile(
   198→  contentRating: AgeRating | string | undefined,
   199→  profile: Profile
   200→): boolean {
   201→  if (!contentRating) return true; // Allow unrated content unless it's a kids profile
   202→
   203→  const rating = contentRating as AgeRating;
   204→  const contentLevel = AGE_RATING_LEVELS[rating];
   205→  const profileMaxLevel = AGE_RATING_LEVELS[profile.maxAgeRating];
   206→
   207→  if (contentLevel === undefined) {
   208→    // Unknown rating - block for kids, allow for others
   209→    return profile.type !== 'kids';
   210→  }
   211→
   212→  return contentLevel <= profileMaxLevel;
   213→}
   214→
   215→// Helper function to check if profile is in kids mode
   216→export function isKidsProfile(profile: Profile | null): boolean {
   217→  return profile?.type === 'kids';
   218→}
