     6→/**
     7→ * WatchedService - Manages "watched" status for movies, episodes, and seasons.
     8→ * Handles both local storage and Trakt sync transparently.
     9→ * 
    10→ * When Trakt is authenticated, it syncs to Trakt.
    11→ * When not authenticated, it stores locally.
    12→ */
    13→class WatchedService {
    14→    private static instance: WatchedService;
    15→    private traktService: TraktService;
    16→
    17→    private constructor() {
    18→        this.traktService = TraktService.getInstance();
    19→    }
    20→
    21→    public static getInstance(): WatchedService {
    22→        if (!WatchedService.instance) {
    23→            WatchedService.instance = new WatchedService();
    24→        }
    25→        return WatchedService.instance;
    26→    }
    27→
    28→    /**
    29→     * Mark a movie as watched
    30→     * @param imdbId - The IMDb ID of the movie
    31→     * @param watchedAt - Optional date when watched
    32→     */
    33→    public async markMovieAsWatched(
    34→        imdbId: string,
    35→        watchedAt: Date = new Date()
    36→    ): Promise<{ success: boolean; syncedToTrakt: boolean }> {
    37→        try {
    38→            logger.log(`[WatchedService] Marking movie as watched: ${imdbId}`);
    39→
    40→            // Check if Trakt is authenticated
    41→            const isTraktAuth = await this.traktService.isAuthenticated();
    42→            let syncedToTrakt = false;
    43→
    44→            if (isTraktAuth) {
    45→                // Sync to Trakt
    46→                syncedToTrakt = await this.traktService.addToWatchedMovies(imdbId, watchedAt);
    47→                logger.log(`[WatchedService] Trakt sync result for movie: ${syncedToTrakt}`);
    48→            }
    49→
    50→            // Also store locally as "completed" (100% progress)
    51→            await this.setLocalWatchedStatus(imdbId, 'movie', true, undefined, watchedAt);
    52→
    53→            return { success: true, syncedToTrakt };
    54→        } catch (error) {
    55→            logger.error('[WatchedService] Failed to mark movie as watched:', error);
    56→            return { success: false, syncedToTrakt: false };
    57→        }
    58→    }
    59→
    60→    /**
    61→     * Mark a single episode as watched
    62→     * @param showImdbId - The IMDb ID of the show
    63→     * @param showId - The Stremio ID of the show (for local storage)
    64→     * @param season - Season number
    65→     * @param episode - Episode number
    66→     * @param watchedAt - Optional date when watched
    67→     */
    68→    public async markEpisodeAsWatched(
    69→        showImdbId: string,
    70→        showId: string,
    71→        season: number,
    72→        episode: number,
    73→        watchedAt: Date = new Date()
