    75→        try {
    76→            logger.log(`[WatchedService] Marking episode as watched: ${showImdbId} S${season}E${episode}`);
    77→
    78→            // Check if Trakt is authenticated
    79→            const isTraktAuth = await this.traktService.isAuthenticated();
    80→            let syncedToTrakt = false;
    81→
    82→            if (isTraktAuth) {
    83→                // Sync to Trakt
    84→                syncedToTrakt = await this.traktService.addToWatchedEpisodes(
    85→                    showImdbId,
    86→                    season,
    87→                    episode,
    88→                    watchedAt
