     5→import React from 'react';
     6→import {
     7→  View,
     8→  Text,
     9→  StyleSheet,
    10→  TouchableOpacity,
    11→} from 'react-native';
    12→import { MaterialIcons } from '@expo/vector-icons';
    13→import { useTheme } from '../../contexts/ThemeContext';
    14→import {
    15→  Profile,
    16→  AVATAR_OPTIONS,
    17→  KIDS_AVATAR_OPTIONS,
    18→  AvatarOption,
    19→} from '../../types/profile';
    20→
    21→interface ProfileCardProps {
    22→  profile: Profile;
    23→  isActive?: boolean;
    24→  isEditMode?: boolean;
    25→  onPress: () => void;
    26→  onEdit?: () => void;
    27→  onDelete?: () => void;
    28→}
    29→
    30→export const ProfileCard: React.FC<ProfileCardProps> = ({
    31→  profile,
    32→  isActive = false,
    33→  isEditMode = false,
    34→  onPress,
    35→  onEdit,
    36→  onDelete,
    37→}) => {
    38→  const { currentTheme } = useTheme();
    39→
    40→  // Find avatar
    41→  const allAvatars = [...AVATAR_OPTIONS, ...KIDS_AVATAR_OPTIONS];
    42→  const avatar: AvatarOption = allAvatars.find(a => a.id === profile.avatarId) || AVATAR_OPTIONS[0];
    43→
    44→  const isKidsProfile = profile.type === 'kids';
    45→
    46→  return (
    47→    <View style={styles.container}>
    48→      <TouchableOpacity
    49→        style={[
    50→          styles.card,
    51→          {
    52→            backgroundColor: isActive
    53→              ? `${currentTheme.colors.primary}20`
    54→              : currentTheme.colors.elevation2,
    55→            borderColor: isActive
    56→              ? currentTheme.colors.primary
    57→              : isKidsProfile
    58→                ? '#FF6B6B50'
    59→                : 'transparent',
    60→          },
    61→        ]}
    62→        onPress={isEditMode ? onEdit : onPress}
    63→        activeOpacity={0.7}
    64→      >
    65→        {/* Edit mode overlay */}
    66→        {isEditMode && (
    67→          <View style={styles.editOverlay}>
    68→            <View
    69→              style={[
    70→                styles.editIcon,
    71→                { backgroundColor: currentTheme.colors.primary },
    72→              ]}
    73→            >
    74→              <MaterialIcons name="edit" size={16} color="#FFF" />
    75→            </View>
    76→          </View>
    77→        )}
    78→
    79→        {/* Avatar */}
    80→        <View
    81→          style={[
    82→            styles.avatarContainer,
    83→            { backgroundColor: avatar.color },
    84→          ]}
    85→        >
    86→          <MaterialIcons
    87→            name={avatar.icon as any}
    88→            size={32}
    89→            color="#FFFFFF"
    90→          />
    91→          {/* PIN indicator */}
    92→          {profile.isPinProtected && !isEditMode && (
    93→            <View
    94→              style={[
    95→                styles.pinIndicator,
    96→                { backgroundColor: currentTheme.colors.darkBackground },
    97→              ]}
    98→            >
    99→              <MaterialIcons name="lock" size={12} color={currentTheme.colors.text} />
   100→            </View>

