     1→import React, { createContext, useContext, useEffect, useMemo, useState, useRef } from 'react';
     2→import accountService, { AuthUser } from '../services/AccountService';
     3→
     4→type AccountContextValue = {
     5→  user: AuthUser | null;
     6→  loading: boolean;
     7→  signIn: (email: string, password: string) => Promise<string | null>;
     8→  signUp: (email: string, password: string) => Promise<string | null>;
     9→  signOut: () => Promise<void>;
    10→  refreshCurrentUser: () => Promise<void>;
    11→  updateProfile: (partial: { avatarUrl?: string; displayName?: string }) => Promise<string | null>;
    12→};
    13→
    14→const AccountContext = createContext<AccountContextValue | undefined>(undefined);
    15→
    16→export const AccountProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    17→  const [user, setUser] = useState<AuthUser | null>(null);
    18→  const [loading, setLoading] = useState(true);
    19→  const loadingTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    20→
    21→  useEffect(() => {
    22→    // Initial user load
    23→    const loadUser = async () => {
    24→      try {
    25→        const u = await accountService.getCurrentUser();
    26→        setUser(u);
    27→      } catch (error) {
    28→        console.warn('[AccountContext] Failed to load user:', error);
    29→      } finally {
    30→        setLoading(false);
    31→      }
    32→    };
    33→
    34→    loadUser();
    35→  }, []);
    36→
    37→  const value = useMemo<AccountContextValue>(() => ({
    38→    user,
    39→    loading,
    40→    signIn: async (email: string, password: string) => {
    41→      const { error } = await accountService.signInWithEmail(email, password);
    42→      return error || null;
    43→    },
    44→    signUp: async (email: string, password: string) => {
    45→      const { error } = await accountService.signUpWithEmail(email, password);
    46→      return error || null;
    47→    },
    48→    signOut: async () => {
    49→      await accountService.signOut();
    50→      setUser(null);
    51→    },
    52→    refreshCurrentUser: async () => {
    53→      // Don't set loading if already loading to avoid conflicts
    54→      if (loading) {
    55→        if (__DEV__) console.log('[AccountContext] Already loading, skipping refresh');
    56→        return;
    57→      }
    58→
    59→      if (__DEV__) console.log('[AccountContext] Starting refreshCurrentUser');
    60→      setLoading(true);
    61→
    62→      // Set a timeout to prevent loading from getting stuck
    63→      loadingTimeoutRef.current = setTimeout(() => {
    64→        console.warn('[AccountContext] Account loading timeout, forcing loading to false');
    65→        setLoading(false);
    66→      }, 5000); // Reduced to 5 seconds for faster fallback
    67→
    68→      try {
    69→        const u = await accountService.getCurrentUser();
    70→        if (__DEV__) console.log('[AccountContext] refreshCurrentUser completed:', u ? 'user found' : 'no user');
    71→        setUser(u);
    72→      } catch (error) {
    73→        console.error('[AccountContext] Failed to refresh current user:', error);
    74→        // Still set user to null on error to ensure we don't get stuck
    75→        setUser(null);
    76→      } finally {
    77→        if (loadingTimeoutRef.current) {
    78→          clearTimeout(loadingTimeoutRef.current);
    79→          loadingTimeoutRef.current = null;
    80→        }
    81→        setLoading(false);
    82→        if (__DEV__) console.log('[AccountContext] refreshCurrentUser finished');
    83→      }
    84→    },
    85→    updateProfile: async (partial) => {
    86→      const err = await accountService.updateProfile(partial);
    87→      if (!err) {
    88→        // Refresh user from server to pick updated fields
    89→        const u = await accountService.getCurrentUser();
    90→        setUser(u);
    91→      }
    92→      return err;
    93→    }
    94→  }), [user, loading]);
    95→
    96→  return (
    97→    <AccountContext.Provider value={value}>
    98→      {children}
    99→    </AccountContext.Provider>
   100→  );
   101→};
   102→
   103→export const useAccount = (): AccountContextValue => {
   104→  const ctx = useContext(AccountContext);
   105→  if (!ctx) throw new Error('useAccount must be used within AccountProvider');
   106→  return ctx;
   107→};
   108→
   109→export default AccountContext;
   110→
   111→

